export function CompanyDashboard() {
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    dashAPI.getStats().then(r => setStats(r.data)).finally(() => setLoading(false));
  }, []);

  if (loading) return <LoadingSpinner fullPage />;

  return (
    <div>
      <PageHeader title="Company Dashboard" breadcrumbs={['Company', 'Dashboard']} />
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <StatCard title="Active Connectors" value={stats?.totalConnectors || 0} icon={<FiUsers />} color="text-blue-600 bg-blue-50" />
        <StatCard title="Onboarded Banks" value={stats?.totalBanks || 0} icon={<FiGrid />} color="text-violet-600 bg-violet-50" />
        <StatCard title="Total Applications" value={stats?.totalApplications || 0} icon={<FiFileText />} color="text-emerald-600 bg-emerald-50" />
        <StatCard title="Pending Requests" value={stats?.pendingRequests || 0} icon={<FiUsers />} color="text-amber-600 bg-amber-50" />
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">This Month</h3>
          <div className="space-y-3 text-sm">
            <div className="flex justify-between py-2 border-b"><span className="text-slate-500">New Applications</span><span className="font-semibold">{stats?.monthApplications || 0}</span></div>
            <div className="flex justify-between py-2 border-b"><span className="text-slate-500">Connected Connectors</span><span className="font-semibold">{stats?.totalConnectors || 0}</span></div>
            <div className="flex justify-between py-2"><span className="text-slate-500">Partner Banks</span><span className="font-semibold">{stats?.totalBanks || 0}</span></div>
          </div>
        </div>
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Quick Actions</h3>
          <div className="grid grid-cols-2 gap-3">
            {[
              { label: 'Join Requests', href: '/company/join-requests', icon: <FiUsers /> },
              { label: 'View Applications', href: '/company/applications', icon: <FiFileText /> },
              { label: 'My Connectors', href: '/company/connectors', icon: <FiUsers /> },
              { label: 'Partner Banks', href: '/company/banks', icon: <FiGrid /> },
            ].map((a, i) => (
              <a key={i} href={a.href} className="flex items-center gap-2 p-3 border border-slate-200 rounded-lg hover:border-primary hover:bg-primary-50 text-slate-700 hover:text-primary transition-all text-sm font-medium">
                {a.icon} {a.label}
              </a>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export function CompanyJoinRequests() {
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'pending' | 'all'>('pending');

  const load = () => {
    setLoading(true);
    joinAPI.getIncoming().then(r => setRequests(r.data)).finally(() => setLoading(false));
  };
  useEffect(() => { load(); }, []);

  const respond = async (id: string, status: 'approved' | 'rejected', note?: string) => {
    try {
      await joinAPI.respond(id, status, note);
      toast.success(`Request ${status}`);
      load();
    } catch { toast.error('Failed'); }
  };

  const filtered = tab === 'pending' ? requests.filter(r => r.status === 'pending') : requests;

  return (
    <div>
      <PageHeader title="Join Requests" subtitle="Manage connector and bank join requests" breadcrumbs={['Company', 'Join Requests']} />

      <div className="flex gap-2 mb-4">
        {(['pending', 'all'] as const).map(t => (
          <button key={t} onClick={() => setTab(t)} className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${tab === t ? 'bg-primary text-white' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
            {t === 'pending' ? `Pending (${requests.filter(r => r.status === 'pending').length})` : 'All Requests'}
          </button>
        ))}
      </div>

      {loading ? <LoadingSpinner /> : filtered.length === 0 ? (
        <EmptyState title="No requests" description={tab === 'pending' ? 'No pending join requests.' : 'No requests yet.'} />
      ) : (
        <div className="space-y-3">
          {filtered.map((r: any) => (
            <div key={r._id} className="card">
              <div className="flex items-start justify-between flex-wrap gap-3">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`badge-${r.fromRole === 'connector' ? 'blue' : 'purple'}`}>{r.fromRole}</span>
                    <StatusBadge status={r.status} />
                  </div>
                  <h3 className="font-semibold text-slate-800">{r.fromUserId?.name}</h3>
                  <p className="text-sm text-slate-500">{r.fromUserId?.email} · {r.fromUserId?.mobile}</p>
                  <p className="text-xs text-slate-400 mt-1">Requested: {new Date(r.requestedAt).toLocaleDateString('en-IN')}</p>
                </div>
                {r.status === 'pending' && (
                  <div className="flex gap-2">
                    <button onClick={() => respond(r._id, 'approved')} className="flex items-center gap-1.5 px-3 py-2 bg-emerald-100 text-emerald-700 rounded-lg text-sm font-medium hover:bg-emerald-200 transition-colors">
                      <FiCheck /> Approve
                    </button>
                    <button onClick={() => respond(r._id, 'rejected', 'Not suitable at this time')} className="flex items-center gap-1.5 px-3 py-2 bg-red-100 text-red-700 rounded-lg text-sm font-medium hover:bg-red-200 transition-colors">
                      <FiX /> Reject
                    </button>
                  </div>
                )}
                {r.status !== 'pending' && (
                  <div className="text-sm text-slate-500">
                    Responded: {r.respondedAt ? new Date(r.respondedAt).toLocaleDateString('en-IN') : '—'}
                    {r.responseNote && <p className="text-xs italic mt-0.5">"{r.responseNote}"</p>}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export function CompanyConnectors() {
  const [connectors, setConnectors] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [importing, setImporting] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', mobile: '' });
  const navigate = useNavigate();

  // const load = () => {
  //   setLoading(true);
  //   companyAPI.getConnectors().then(r => setConnectors(r.data)).finally(() => setLoading(false));
  // };
  
  
  //shree
  const load = () => {
  setLoading(true);
  companyAPI.getConnectors()
    .then(r => setConnectors(Array.isArray(r.data) ? r.data : r.data.connectors ?? []))
    .finally(() => setLoading(false));
};
  
  
  useEffect(() => { load(); }, []);

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    setImporting(true);
    try {
      const res = await adminAPI.importExcel('connectors', file);
      toast.success(res.data.message); load();
    } catch { toast.error('Import failed'); } finally { setImporting(false); }
  };

  const downloadTemplate = async () => {
    const res = await adminAPI.getImportTemplate('connectors');
    const url = URL.createObjectURL(new Blob([res.data]));
    const a = document.createElement('a'); a.href = url; a.download = 'connectors_template.xlsx'; a.click();
  };

  return (
    <div>
      <PageHeader title="My Connectors" subtitle={`${connectors.length} connected connectors`} breadcrumbs={['Company', 'Connectors']}
        actions={<>
          <button className="btn-secondary flex items-center gap-2 text-sm" onClick={downloadTemplate}><FiDownload /> Template</button>
          <label className="btn-secondary flex items-center gap-2 text-sm cursor-pointer">
            <FiUpload /> {importing ? 'Importing...' : 'Import'}
            <input type="file" accept=".xlsx,.xls" className="hidden" onChange={handleImport} />
          </label>
          <button className="btn-primary flex items-center gap-2 text-sm" onClick={() => setShowAdd(true)}><FiPlus /> Add Connector</button>
        </>} />

      {loading ? <LoadingSpinner /> : connectors.length === 0 ? (
        <EmptyState title="No connectors yet" description="Add connectors manually or wait for join requests." />
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {connectors.map((c: any) => (
            <div key={c._id} className="card">
              <div className="flex items-start justify-between mb-3">
                <div className="w-10 h-10 rounded-full bg-primary-100 flex items-center justify-center text-primary font-bold">
                  {c.name?.charAt(0) || c.userId?.name?.charAt(0)}
                </div>
                <StatusBadge status={c.status} />
              </div>
              <h3 className="font-semibold text-slate-800">{c.name || c.userId?.name}</h3>
              <p className="text-sm text-slate-500">{c.email || c.userId?.email}</p>
              <p className="text-sm text-slate-500">{c.mobile || c.userId?.mobile}</p>
              <div className="flex justify-between mt-3 pt-3 border-t text-sm">
                <span className="text-slate-500">Total Leads: <span className="font-semibold text-slate-700">{c.totalLeads || 0}</span></span>
                <span className="text-slate-500">Approved: <span className="font-semibold text-emerald-600">{c.totalApproved || 0}</span></span>
              </div>
            </div>
          ))}
        </div>
      )}

      <Modal open={showAdd} onClose={() => setShowAdd(false)} title="Add Connector">
        <div className="space-y-4">
          <div><label className="label">Name *</label><input className="input" value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} /></div>
          <div><label className="label">Email *</label><input className="input" type="email" value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))} /></div>
          <div><label className="label">Mobile</label><input className="input" value={form.mobile} onChange={e => setForm(p => ({ ...p, mobile: e.target.value }))} /></div>
          <p className="text-xs text-slate-400">Default password will be Connector@123. The connector can change it after login.</p>
          <div className="flex gap-3 justify-end">
            <button className="btn-secondary" onClick={() => setShowAdd(false)}>Cancel</button>
           <button className="btn-primary" onClick={async () => {
  try {
    await companyAPI.createConnector({ ...form, password: 'Connector@123' }); // ← companyAPI not adminAPI
    toast.success('Connector added');
    setShowAdd(false);
    setForm({ name: '', email: '', mobile: '' });
    load();
  } catch (err: any) {
    toast.error(err?.response?.data?.message || 'Failed');
  }
}}>Add Connector</button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

