export function CompanyEarnings() {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    commissionAPI.getAll().then(r => setData(r.data)).finally(() => setLoading(false));
  }, []);

  const totalEarned = data?.commissions?.reduce((s: number, c: any) => s + (c.commissionAmount || 0), 0) || 0;
  const paid = data?.commissions?.filter((c: any) => c.status === 'paid').reduce((s: number, c: any) => s + (c.commissionAmount || 0), 0) || 0;
  const pending = totalEarned - paid;

  return (
    <div>
      <PageHeader title="Earnings & Commissions" breadcrumbs={['Company', 'Earnings']} />
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <StatCard title="Total Earnings" value={`₹${totalEarned.toLocaleString('en-IN')}`} icon={<FiDollarSign />} color="text-emerald-600 bg-emerald-50" />
        <StatCard title="Paid" value={`₹${paid.toLocaleString('en-IN')}`} icon={<FiDollarSign />} color="text-blue-600 bg-blue-50" />
        <StatCard title="Pending" value={`₹${pending.toLocaleString('en-IN')}`} icon={<FiDollarSign />} color="text-amber-600 bg-amber-50" />
      </div>
      <div className="card">
        {loading ? <LoadingSpinner /> : !data?.commissions?.length ? (
          <EmptyState title="No earnings yet" description="Commissions will appear when loans are disbursed through your network." />
        ) : (
          <table className="w-full">
            <thead className="bg-slate-50">
              <tr><th className="table-th">App ID</th><th className="table-th">Loan Type</th><th className="table-th">Disbursed Amount</th><th className="table-th">Rate</th><th className="table-th">Commission</th><th className="table-th">Status</th><th className="table-th">Date</th></tr>
            </thead>
            <tbody>
              {data.commissions.map((c: any) => (
                <tr key={c._id} className="table-row">
                  <td className="table-td font-mono text-xs text-primary">{c.applicationId?.applicationId}</td>
                  <td className="table-td text-sm">{c.loanType}</td>
                  <td className="table-td">₹{(c.loanAmount || 0).toLocaleString('en-IN')}</td>
                  <td className="table-td">{c.commissionRate}%</td>
                  <td className="table-td font-semibold text-emerald-600">₹{(c.commissionAmount || 0).toLocaleString('en-IN')}</td>
                  <td className="table-td"><StatusBadge status={c.status} /></td>
                  <td className="table-td text-xs">{new Date(c.createdAt).toLocaleDateString('en-IN')}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

export function CompanyMessages() {
  const [messages, setMessages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCompose, setShowCompose] = useState(false);
  //Raksha
 const [form, setForm] = useState({ toUserId: '', broadcastRole: 'admin', subject: '', body: '' });

  const load = () => { setLoading(true); msgAPI.getAll().then(r => setMessages(r.data)).finally(() => setLoading(false)); };
  useEffect(() => { load(); }, []);
//raksha
  const send = async () => {
  try { await msgAPI.send(form); toast.success('Message sent'); setShowCompose(false); load(); }
  catch (err: any) { 
    const msg = err?.response?.data?.message || err?.message || 'Failed';
    toast.error(msg);
    console.error('Send message error:', err?.response?.data || err);
  }
};

  return (
    <div>
      <PageHeader title="Messages" breadcrumbs={['Company', 'Messages']}
        actions={<button className="btn-primary text-sm" onClick={() => setShowCompose(true)}>Compose</button>} />
      <div className="card">
        {loading ? <LoadingSpinner /> : messages.length === 0 ? <EmptyState title="No messages" /> : (
          <div className="divide-y divide-slate-100">
            {messages.map((m: any) => (
              <div key={m._id} className="py-3 px-2 hover:bg-slate-50">
                <div className="flex items-center justify-between">
                  <span className="font-medium text-slate-800 text-sm">{m.subject}</span>
                  <span className="text-xs text-slate-400">{new Date(m.createdAt).toLocaleDateString('en-IN')}</span>
                </div>
                <p className="text-xs text-slate-500 mt-0.5">From: {m.fromUserId?.name}</p>
                <p className="text-sm text-slate-600 mt-1">{m.body}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <Modal open={showCompose} onClose={() => setShowCompose(false)} title="Compose Message">
        <div className="space-y-4">
          <div><label className="label">Subject *</label><input className="input" value={form.subject} onChange={e => setForm(p => ({ ...p, subject: e.target.value }))} /></div>
          <div><label className="label">Message *</label><textarea className="input h-24 resize-none" value={form.body} onChange={e => setForm(p => ({ ...p, body: e.target.value }))} /></div>
          <div className="flex gap-3 justify-end">
            <button className="btn-secondary" onClick={() => setShowCompose(false)}>Cancel</button>
            <button className="btn-primary" onClick={send}>Send</button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

