import React, {
  createContext, useContext, useState,
  useEffect, useCallback, useRef
} from 'react';
import { authAPI } from '../services/api';
import { io, Socket } from 'socket.io-client';

interface User {
  _id: string; name: string; email: string;
  role: string; mobile?: string; profilePhoto?: string; status: string;
}
interface AuthCtx {
  user: User | null; profile: any; loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  updateUser: (u: Partial<User>) => void;
  socket: Socket | null;
  unreadCount: number;
  setUnreadCount: React.Dispatch<React.SetStateAction<number>>;
}

const AuthContext = createContext<AuthCtx>({} as AuthCtx);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser]               = useState<User | null>(null);
  const [profile, setProfile]         = useState<any>(null);
  const [loading, setLoading]         = useState(true);
  const [socket, setSocket]           = useState<Socket | null>(null);
  const [unreadCount, setUnreadCount] = useState(0);

  // Prevent double-login calls (HMR / StrictMode)
  const loginInFlight = useRef(false);
  // Hold socket ref so we can disconnect before creating a new one
  const socketRef = useRef<Socket | null>(null);

  const initSocket = useCallback((userId: string) => {
    // Tear down any existing socket first
    if (socketRef.current) {
      socketRef.current.disconnect();
      socketRef.current = null;
    }

    const s = io(process.env.REACT_APP_SOCKET_URL || '', {
      transports: ['websocket'],
      // Reconnect automatically, but cap attempts so we don't spam in dev
      reconnectionAttempts: 5,
    });

    s.on('connect', () => s.emit('join', userId));
    s.on('notification', () => setUnreadCount(c => c + 1));

    socketRef.current = s;
    setSocket(s);
  }, []); // no deps — stable for the lifetime of the provider

  // Restore session on mount
  useEffect(() => {
    const token = localStorage.getItem('accessToken');
    if (!token) { setLoading(false); return; }

    authAPI.me()
      .then(res => {
        setUser(res.data.user);
        setProfile(res.data.profile);
        initSocket(res.data.user._id);
      })
      .catch(async () => {
        // Try a silent token refresh before giving up
        const refreshToken = localStorage.getItem('refreshToken');
        if (refreshToken) {
          try {
            const r = await authAPI.refresh(refreshToken);
            localStorage.setItem('accessToken', r.data.accessToken);
            const me = await authAPI.me();
            setUser(me.data.user);
            setProfile(me.data.profile);
            initSocket(me.data.user._id);
            return;
          } catch { /* refresh failed — fall through to clear */ }
        }
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
      })
      .finally(() => setLoading(false));

    // Cleanup on unmount (React StrictMode fires this twice in dev)
    return () => {
      socketRef.current?.disconnect();
      socketRef.current = null;
    };
  }, [initSocket]);

  const login = async (email: string, password: string) => {
    if (loginInFlight.current) return; // guard against double-fire
    loginInFlight.current = true;

    try {
      const res = await authAPI.login({ email, password });
      localStorage.setItem('accessToken', res.data.accessToken);
      if (res.data.refreshToken) {
        localStorage.setItem('refreshToken', res.data.refreshToken);
      }

      // Single me() call — no need to duplicate what mount already does
      const me = await authAPI.me();
      setUser(me.data.user);
      setProfile(me.data.profile);
      initSocket(me.data.user._id);
    } finally {
      loginInFlight.current = false;
    }
  };

  const logout = async () => {
    try { await authAPI.logout(); } catch { /* best-effort */ }

    socketRef.current?.disconnect();
    socketRef.current = null;

    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    setUser(null);
    setProfile(null);
    setSocket(null);
    setUnreadCount(0); // reset badge on logout
  };

  const updateUser = (u: Partial<User>) =>
    setUser(prev => prev ? { ...prev, ...u } : null);

  return (
    <AuthContext.Provider value={{
      user, profile, loading,
      login, logout, updateUser,
      socket, unreadCount, setUnreadCount,
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);