import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_URL || 'https://bankzone.etpl.ai/api/v1';
//5000


const api = axios.create({ baseURL: API_BASE, withCredentials: true });

// Request interceptor – attach access token
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('accessToken');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Response interceptor – handle 401, try refresh
api.interceptors.response.use(
  (res) => res,
  async (err) => {
    const original = err.config;
    if (err.response?.status === 401 && !original._retry) {
      original._retry = true;
      try {
        const refreshToken = localStorage.getItem('refreshToken');
        const res = await axios.post(`${API_BASE}/auth/refresh`, { refreshToken });
        localStorage.setItem('accessToken', res.data.accessToken);
        if (res.data.refreshToken) localStorage.setItem('refreshToken', res.data.refreshToken);
        original.headers.Authorization = `Bearer ${res.data.accessToken}`;
        return api(original);
      } catch {
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
        window.location.href = '/login';
      }
    }
    return Promise.reject(err);
  }
);

export default api;

// Auth
export const authAPI = {
  login: (data: any) => api.post('/auth/login', data),
  register: (data: any) => api.post('/auth/register', data),
  logout: () => api.post('/auth/logout'),
  me: () => api.get('/auth/me'),
  changePassword: (data: any) => api.put('/auth/change-password', data),
  refresh: (refreshToken: string) => api.post('/auth/refresh', { refreshToken }),
};

// Admin
export const adminAPI = {
  getDashboard: () => api.get('/admin/dashboard/stats'),
  getBanks: (params?: any) => api.get('/admin/banks', { params }),
  createBank: (data: any) => api.post('/admin/banks', data),
  updateBank: (id: string, data: any) => api.put(`/admin/banks/${id}`, data),
  deleteBank: (id: string) => api.delete(`/admin/banks/${id}`),
  getCompanies: (params?: any) => api.get('/admin/companies', { params }),
  deleteCompany: (id: string) => api.delete(`/admin/companies/${id}`),
  createCompany: (data: any) => api.post('/admin/companies', data),
  updateCompany: (id: string, data: any) => api.put(`/admin/companies/${id}`, data),
  getConnectors: (params?: any) => api.get('/admin/connectors', { params }),
  createConnector: (data: any) => api.post('/admin/connectors', data),
  getAllApplications: (params?: any) => api.get('/admin/applications', { params }),
  getUsers: (params?: any) => api.get('/admin/users', { params }),
  updateUserStatus: (id: string, status: string) => api.put(`/admin/users/${id}/status`, { status }),
  getAuditLogs: (params?: any) => api.get('/admin/audit-logs', { params }),
  getReports: (params?: any) => api.get('/admin/reports', { params }),
  exportExcel: (entity: string) => api.get(`/admin/export/${entity}`, { responseType: 'blob' }),
  importExcel: (entity: string, file: File) => {
    const fd = new FormData(); fd.append('file', file);
    return api.post(`/admin/import/${entity}`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
  },
  getImportTemplate: (entity: string) => api.get(`/admin/import-template/${entity}`, { responseType: 'blob' }),
};

// Applications
export const appAPI = {
  create: (data: any) => api.post('/applications', data),
  getAll: (params?: any) => api.get('/applications', { params }),
  getById: (id: string) => api.get(`/applications/${id}`),
  updateStatus: (id: string, bankId: string, data: any) => api.post(`/applications/${id}/banks/${bankId}/status`, data),
  raiseQuery: (id: string, bankId: string, question: string) => api.post(`/applications/${id}/banks/${bankId}/query`, { question }),
  replyQuery: (id: string, bankId: string, queryId: string, answer: string) => api.post(`/applications/${id}/banks/${bankId}/query/${queryId}/reply`, { answer }),
  requestUnmask: (id: string, bankId: string) => api.post(`/applications/${id}/banks/${bankId}/unmask-request`),
  approveUnmask: (id: string, bankId: string) => api.post(`/applications/${id}/banks/${bankId}/unmask-approve`),
  selectBank: (id: string, bankId: string) => api.post(`/applications/${id}/banks/${bankId}/select`),
  updateInterest: (id: string, bankId: string, data: any) => api.post(`/applications/${id}/banks/${bankId}/interest`, data),
  downloadDocs: (id: string, bankId: string) => api.post(`/applications/${id}/banks/${bankId}/download-docs`),
  generatePDF: (id: string) => api.get(`/applications/${id}/pdf`, { responseType: 'blob' }),
  uploadDoc: (file: File, folder: string) => {
    const fd = new FormData(); fd.append('file', file);
    return api.post(`/documents/upload?folder=${folder}`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
  },
  uploadMultiple: (files: File[], folder: string) => {
    const fd = new FormData(); files.forEach(f => fd.append('files', f));
    return api.post(`/documents/upload-multiple?folder=${folder}`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
  },
  getNotificationDetail: (id: string) => api.get(`/applications/${id}/notification-detail`),  // <-raksha
};

