export function AdminApplications() {
  const [apps, setApps] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<any>(null);
  const [filters, setFilters] = useState({
    loanType: '',
    status: '',      // maps to overallStatus on backend
    page: 1,
    limit: 10,       // ← NEW: dynamic limit
  });
  const [total, setTotal] = useState(0);

  const load = () => {
  setLoading(true);
  adminAPI.getAllApplications({
    loanType: filters.loanType || undefined,
    status:   filters.status   || undefined,
    page:     filters.page,
    limit:    filters.limit,
  })
    .then(r => {
      setApps(r.data.applications);
      setTotal(r.data.total);
    })
    .finally(() => setLoading(false));
};

  // reload whenever any filter changes
  useEffect(() => { load(); }, [filters.loanType, filters.status, filters.page, filters.limit]);

  const totalPages = Math.ceil(total / filters.limit);

  const handleExport = async () => {
    try {
      const res = await adminAPI.exportExcel('applications');
      const url = URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a');
      a.href = url; a.download = `applications_${Date.now()}.xlsx`; a.click();
    } catch { toast.error('Export failed'); }
  };

  const handlePDF = async (id: string) => {
    try {
      const res = await appAPI.generatePDF(id);
      const url = URL.createObjectURL(new Blob([res.data], { type: 'application/pdf' }));
      window.open(url, '_blank');
    } catch { toast.error('PDF generation failed'); }
  };

  return (
    <div>
      <PageHeader
        title="All Applications"
        subtitle={`${total} total applications`}
        breadcrumbs={['Admin', 'Applications']}
        actions={
          <button className="btn-secondary flex items-center gap-2 text-sm" onClick={handleExport}>
            <FiDownload /> Export Excel
          </button>
        }
      />

      {/* ── Filters ── */}
      <div className="card mb-4">
        <div className="flex flex-wrap gap-3 items-center">

          {/* Loan Type
          <select
            className="input w-auto"
            value={filters.loanType}
            onChange={e => setFilters(p => ({ ...p, loanType: e.target.value, page: 1 }))}
          >
            <option value="">All Loan Types</option>
            {LOAN_TYPES.map(lt => <option key={lt} value={lt}>{lt}</option>)}
          </select> */}

          {/* h-4/7 */}
{/* Loan Type */}
<LoanTypeDropdown
  value={filters.loanType}
  onChange={(v) => setFilters(p => ({ ...p, loanType: v, page: 1 }))}
  options={LOAN_TYPES}
/>


          {/* Status — values must match overallStatus values in DB */}
          <select
            className="input w-auto"
            value={filters.status}
            onChange={e => setFilters(p => ({ ...p, status: e.target.value, page: 1 }))}
          >
            <option value="">All Status</option>
            <option value="active">Active</option>
            <option value="closed">Closed</option>
            <option value="rejected">Rejected</option>
            <option value="disbursed">Disbursed</option>
            <option value="sanctioned">Sanctioned</option>
          </select>

          {/* ── Rows per page ── */}
          <select
            className="input w-auto"
            value={filters.limit}
            onChange={e => setFilters(p => ({ ...p, limit: Number(e.target.value), page: 1 }))}
          >
            <option value={5}>5 / page</option>
            <option value={10}>10 / page</option>
            <option value={15}>15 / page</option>
            <option value={20}>20 / page</option>
          </select>

          <button
            className="btn-secondary flex items-center gap-2 text-sm"
            onClick={() => setFilters({ loanType: '', status: '', page: 1, limit: 10 })}
          >
            <FiFilter /> Clear
          </button>
        </div>
      </div>

      {/* ── Table ── */}
      <div className="card">
        {loading ? (
          <LoadingSpinner />
        ) : apps.length === 0 ? (
          <EmptyState title="No applications found" />
        ) : (
          <>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-slate-50">
                  <tr>
                    <th className="table-th">App ID</th>
                    <th className="table-th">Applicant</th>
                    <th className="table-th">Loan Type</th>
                    <th className="table-th">Amount</th>
                    <th className="table-th">Connector</th>
                    <th className="table-th">CIBIL</th>
                    <th className="table-th">Banks</th>
                    <th className="table-th">Status</th>
                    <th className="table-th">Date</th>
                    <th className="table-th">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {apps.map((a: any) => (
                    <tr key={a._id} className="table-row">
                      <td className="table-td font-mono text-xs font-bold text-primary">{a.applicationId}</td>
                      <td className="table-td font-medium">{a.applicantDetails?.name || '—'}</td>
                      <td className="table-td text-xs">{a.loanType}</td>
                      <td className="table-td">₹{(a.loanAmount || 0).toLocaleString('en-IN')}</td>
                      <td className="table-td text-sm">{a.connectorId?.name || '—'}</td>
                      <td className="table-td">
                        <span className={`font-bold text-sm ${
                          (a.cibilScore || 0) >= 750 ? 'text-emerald-600' :
                          (a.cibilScore || 0) >= 650 ? 'text-amber-600' : 'text-red-500'
                        }`}>
                          {a.cibilScore || '—'}
                        </span>
                      </td>
                      <td className="table-td">{a.bankAssignments?.length || 0} bank(s)</td>
                      <td className="table-td"><StatusBadge status={a.overallStatus} /></td>
                      <td className="table-td text-xs">{new Date(a.createdAt).toLocaleDateString('en-IN')}</td>
                      <td className="table-td">
                        <div className="flex gap-1">
                          <button onClick={() => setSelected(a)} className="p-1 text-primary hover:text-primary-700"><FiEye /></button>
                          <button onClick={() => handlePDF(a._id)} className="p-1 text-slate-500 hover:text-slate-700"><FiDownload /></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* ── Pagination ── */}
            <div className="flex items-center justify-between pt-4 mt-4 border-t border-slate-100">
              <span className="text-sm text-slate-500">
                Showing {(filters.page - 1) * filters.limit + 1}–
                {Math.min(filters.page * filters.limit, total)} of {total}
              </span>

              <div className="flex items-center gap-1">
                {/* First */}
                <button
                  className="btn-secondary text-sm px-2 py-1.5"
                  disabled={filters.page === 1}
                  onClick={() => setFilters(p => ({ ...p, page: 1 }))}
                >«</button>

                {/* Prev */}
                <button
                  className="btn-secondary text-sm px-3 py-1.5"
                  disabled={filters.page === 1}
                  onClick={() => setFilters(p => ({ ...p, page: p.page - 1 }))}
                >Prev</button>

                {/* Page numbers — show up to 5 around current */}
                {Array.from({ length: totalPages }, (_, i) => i + 1)
                  .filter(n => n === 1 || n === totalPages || Math.abs(n - filters.page) <= 1)
                  .reduce<(number | '...')[]>((acc, n, idx, arr) => {
                    if (idx > 0 && (arr[idx - 1] as number) + 1 < n) acc.push('...');
                    acc.push(n);
                    return acc;
                  }, [])
                  .map((n, i) =>
                    n === '...' ? (
                      <span key={`ellipsis-${i}`} className="px-2 text-slate-400 text-sm">…</span>
                    ) : (
                      <button
                        key={n}
                        className={`text-sm px-3 py-1.5 rounded-lg border transition-colors ${
                          filters.page === n
                            ? 'bg-primary text-white border-primary'
                            : 'btn-secondary'
                        }`}
                        onClick={() => setFilters(p => ({ ...p, page: n as number }))}
                      >
                        {n}
                      </button>
                    )
                  )
                }

                {/* Next */}
                <button
                  className="btn-secondary text-sm px-3 py-1.5"
                  disabled={filters.page >= totalPages}
                  onClick={() => setFilters(p => ({ ...p, page: p.page + 1 }))}
                >Next</button>

                {/* Last */}
                <button
                  className="btn-secondary text-sm px-2 py-1.5"
                  disabled={filters.page >= totalPages}
                  onClick={() => setFilters(p => ({ ...p, page: totalPages }))}
                >»</button>
              </div>
            </div>
          </>
        )}
      </div>

      {/* ── Detail Modal (unchanged) ── */}
      <Modal open={!!selected} onClose={() => setSelected(null)} title={`Application: ${selected?.applicationId}`} size="max-w-3xl">
        {selected && (
          <div className="space-y-4 max-h-[70vh] overflow-y-auto">
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4 text-sm">
              <div><span className="text-slate-500">Loan Type:</span> <span className="font-medium">{selected.loanType}</span></div>
              <div><span className="text-slate-500">Amount:</span> <span className="font-medium">₹{(selected.loanAmount || 0).toLocaleString('en-IN')}</span></div>
              <div><span className="text-slate-500">CIBIL:</span> <span className="font-bold">{selected.cibilScore || '—'}</span></div>
              <div><span className="text-slate-500">Applicant:</span> <span className="font-medium">{selected.applicantDetails?.name}</span></div>
              <div><span className="text-slate-500">Mobile:</span> <span className="font-medium">{selected.applicantDetails?.mobileRaw || selected.applicantDetails?.mobileMasked}</span></div>
              <div><span className="text-slate-500">Email:</span> <span className="font-medium">{selected.applicantDetails?.email || selected.applicantDetails?.emailMasked}</span></div>
              <div><span className="text-slate-500">Employment:</span> <span className="font-medium">{selected.incomeDetails?.employmentType}</span></div>
              <div><span className="text-slate-500">Company:</span> <span className="font-medium">{selected.incomeDetails?.companyName}</span></div>
              <div><span className="text-slate-500">Salary:</span> <span className="font-medium">₹{(selected.incomeDetails?.netSalary || 0).toLocaleString('en-IN')}</span></div>
            </div>
            <div>
              <h4 className="font-semibold text-slate-700 mb-3">Bank Assignments</h4>
              {selected.bankAssignments?.map((ba: any) => (
                <div key={ba._id} className="border border-slate-200 rounded-lg p-4 mb-3">
                  <div className="flex items-center justify-between mb-2">
                    <span className="font-semibold text-slate-800">{ba.bankName}</span>
                    <StatusBadge status={ba.status} />
                  </div>
                  {ba.statusHistory?.length > 0 && <StageTimeline history={ba.statusHistory} />}
                </div>
              ))}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

export function AdminUsers() {
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [roleFilter, setRoleFilter] = useState('');
  const [search, setSearch] = useState('');

// h-4/7
const ROLE_LABELS: Record<string, string> = {
  admin: 'Admin', company: 'Company', bank: 'Bank', connector: 'Connector', sm: 'Sales Manager'
};

  const load = () => { setLoading(true); adminAPI.getUsers({ role: roleFilter }).then(r => setUsers(r.data.users)).finally(() => setLoading(false)); };
  useEffect(() => { load(); }, [roleFilter]);

  const toggleStatus = async (u: any) => {
    const newStatus = u.status === 'active' ? 'blocked' : 'active';
    await adminAPI.updateUserStatus(u._id, newStatus);
    toast.success(`User ${newStatus}`);
    load();
  };

  const filtered = users.filter(u => u.name?.toLowerCase().includes(search.toLowerCase()) || u.email?.toLowerCase().includes(search.toLowerCase()));

  return (
    <div>
      <PageHeader title="User Management" subtitle={`${users.length} users`} breadcrumbs={['Admin', 'Users']} />
      <div className="card">
        <div className="flex flex-wrap gap-3 mb-4">
          <input className="input max-w-xs" placeholder="Search users..." value={search} onChange={e => setSearch(e.target.value)} />
          {/* <select className="input w-auto" value={roleFilter} onChange={e => setRoleFilter(e.target.value)}>
            <option value="">All Roles</option>
            <option value="admin">Admin</option>
            <option value="company">Company</option>
            <option value="bank">Bank</option>
            <option value="connector">Connector</option>
            <option value="sm">Sales Manager</option>
          </select> */}

{/* h-4/7 */}
<LoanTypeDropdown
  value={roleFilter}
  onChange={setRoleFilter}
  options={['admin', 'company', 'bank', 'connector', 'sm']}
  placeholder="All Roles"
/>


        </div>
        {loading ? <LoadingSpinner /> : filtered.length === 0 ? <EmptyState title="No users found" /> : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50">
                <tr><th className="table-th">Name</th><th className="table-th">Email</th><th className="table-th">Role</th><th className="table-th">Mobile</th><th className="table-th">Status</th><th className="table-th">Last Login</th><th className="table-th">Action</th></tr>
              </thead>
              <tbody>
                {filtered.map((u: any) => (
                  <tr key={u._id} className="table-row">
                    <td className="table-td font-medium">{u.name}</td>
                    <td className="table-td text-sm">{u.email}</td>
                    <td className="table-td"><span className="badge-blue capitalize">{u.role}</span></td>
                    <td className="table-td">{u.mobile || '—'}</td>
                    <td className="table-td"><StatusBadge status={u.status} /></td>
                    <td className="table-td text-xs">{u.lastLogin ? new Date(u.lastLogin).toLocaleDateString('en-IN') : 'Never'}</td>
                    <td className="table-td">
                      {u.role !== 'admin' && (
                        <button onClick={() => toggleStatus(u)} className={`text-xs px-2 py-1 rounded border ${u.status === 'active' ? 'border-red-300 text-red-600 hover:bg-red-50' : 'border-green-300 text-green-600 hover:bg-green-50'}`}>
                          {u.status === 'active' ? 'Block' : 'Unblock'}
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

export function AdminReports() {
  const [type, setType] = useState('monthly');
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const load = () => {
    setLoading(true);
    adminAPI.getReports({ type }).then(r => setData(r.data)).finally(() => setLoading(false));
  };
  useEffect(() => { load(); }, [type]);

  const exportReport = async (entity: string) => {
    try {
      const res = await adminAPI.exportExcel(entity);
      const url = URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a'); a.href = url; a.download = `${entity}_report.xlsx`; a.click();
    } catch { toast.error('Export failed'); }
  };

  return (
    <div>
      <PageHeader title="Reports" breadcrumbs={['Admin', 'Reports']} />
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        {['applications','banks','companies','connectors'].map(e => (
          <button key={e} onClick={() => exportReport(e)} className="card flex items-center gap-2 text-sm font-medium text-slate-700 hover:border-primary hover:text-primary transition-all border border-slate-200 cursor-pointer">
            <FiDownload className="text-primary" /> Export {e.charAt(0).toUpperCase() + e.slice(1)}
          </button>
        ))}
      </div>

      <div className="card">
        <div className="flex flex-wrap gap-3 mb-6">
          {['monthly','bank-wise','connector-wise','tat'].map(t => (
            <button key={t} onClick={() => setType(t)} className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${type === t ? 'bg-primary text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}>
              {t.replace('-', ' ').replace(/\b\w/g, c => c.toUpperCase())}
            </button>
          ))}
        </div>

        {loading ? <LoadingSpinner /> : !data ? <EmptyState title="Select a report type" /> : (
          <div>
            <h3 className="font-semibold text-slate-800 mb-4">{type.replace('-', ' ').replace(/\b\w/g, c => c.toUpperCase())} Report</h3>
            {Array.isArray(data.data) && data.data.length === 0 ? (
              <EmptyState title="No data available for this report" />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-slate-50">
                    <tr>
                      {type === 'monthly' && <><th className="table-th">Period</th><th className="table-th">Applications</th><th className="table-th">Amount</th></>}
                      {type === 'bank-wise' && <><th className="table-th">Bank</th><th className="table-th">Total</th><th className="table-th">Accepted</th><th className="table-th">Sanctioned</th></>}
                      {type === 'connector-wise' && <><th className="table-th">Connector</th><th className="table-th">Total Leads</th></>}
                      {type === 'tat' && <><th className="table-th">App ID</th><th className="table-th">Applicant</th><th className="table-th">Connector</th><th className="table-th">Company</th></>}
                    </tr>
                  </thead>
                  <tbody>
                    {Array.isArray(data.data) && data.data.map((row: any, i: number) => (
                      <tr key={i} className="table-row">
                        {type === 'monthly' && (
                          <>
                         <td className="table-td">{String(row._id?.month ?? '')}/{String(row._id?.year ?? '')}</td>
                        <td className="table-td">{row.count}</td>
                        <td className="table-td">₹{(row.amount || 0).toLocaleString('en-IN')}</td>
                        </>
                      )}
                        {type === 'bank-wise' && (
                          <>
                          <td className="table-td font-medium">{String(row._id ?? '—')}</td>
                          <td className="table-td">{row.total}</td>
                          <td className="table-td">{row.accepted}</td>
                          <td className="table-td">{row.sanctioned}</td></>)}
                        {type === 'connector-wise' && (
                          <>
                          <td className="table-td">{row.connector?.[0]?.name || String(row._id)}</td>
                          <td className="table-td">{row.total}</td>
                          </>
                        )}
                        {type === 'tat' && (
        <>
          <td className="table-td font-mono text-xs">{row.applicationId}</td>
          <td className="table-td">{row.applicantDetails?.name || '—'}</td>
          <td className="table-td">{row.connectorId?.name || '—'}</td>
          <td className="table-td">{row.companyId?.companyName || '—'}</td>
        </>
      )}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

