export function AdminAuditLogs() {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [totalPages, setTotalPages] = useState(1);
  const [limit, setLimit] = useState(10);          // ← new

  const load = () => {
    setLoading(true);
    adminAPI
      .getAuditLogs({ page, limit })               // ← pass limit
      .then((r) => {
        setLogs(r.data.logs);
        setTotal(r.data.total);
        setTotalPages(r.data.pages);
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [page, limit]);     // ← depend on limit

  const handleLimitChange = (newLimit: number) => {
    setLimit(newLimit);
    setPage(1);                                    // ← reset to page 1 on limit change
  };

  return (
    <div>
      <PageHeader
        title="Audit Logs"
        subtitle={`${total} total events`}
        breadcrumbs={['Admin', 'Audit Logs']}
      />
      <div className="card">

        {/* ── Limit filter ── */}
        <div className="flex items-center gap-2 mb-4">
          <span className="text-sm text-slate-500">Rows per page:</span>
          {[5, 10, 15].map((n) => (
            <button
              key={n}
              onClick={() => handleLimitChange(n)}
              className={`px-3 py-1 rounded text-sm font-medium border transition-colors
                ${limit === n
                  ? 'bg-blue-600 text-white border-blue-600'
                  : 'bg-white text-slate-600 border-slate-300 hover:border-blue-400'
                }`}
            >
              {n}
            </button>
          ))}
        </div>

        {loading ? (
          <LoadingSpinner />
        ) : logs.length === 0 ? (
          <EmptyState title="No logs yet" />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50">
                <tr>
                  <th className="table-th">Time</th>
                  <th className="table-th">User</th>
                  <th className="table-th">Role</th>
                  <th className="table-th">Action</th>
                  <th className="table-th">Description</th>
                  <th className="table-th">IP</th>
                </tr>
              </thead>
              <tbody>
                {logs.map((l: any) => (
                  <tr key={l._id} className="table-row">
                    <td className="table-td text-xs whitespace-nowrap">
                      {new Date(l.createdAt).toLocaleString('en-IN')}
                    </td>
                    <td className="table-td font-medium text-sm">{l.userId?.name || '—'}</td>
                    <td className="table-td">
                      <span className="badge-blue capitalize text-xs">{l.role}</span>
                    </td>
                    <td className="table-td font-mono text-xs">{l.action}</td>
                    <td className="table-td text-sm">{l.description}</td>
                    <td className="table-td font-mono text-xs">{l.ipAddress || '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <div className="flex items-center gap-2 justify-end mt-4">
          <button
            className="btn-secondary text-sm px-3 py-1.5"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Prev
          </button>
          <span className="text-sm text-slate-500">
            Page {page} of {totalPages}
          </span>
          <button
            className="btn-secondary text-sm px-3 py-1.5"
            disabled={page >= totalPages}
            onClick={() => setPage((p) => p + 1)}
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}

export function AdminMessages() {
  const [messages, setMessages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCompose, setShowCompose] = useState(false);
  const [form, setForm] = useState({ toUserId: '', broadcastRole: '', subject: '', body: '' });
  // msgAPI imported at top

  const load = () => { setLoading(true); msgAPI.getAll().then((r: any) => setMessages(r.data)).finally(() => setLoading(false)); };
  useEffect(() => { load(); }, []);

  const send = async () => {
    try { await msgAPI.send(form); toast.success('Message sent'); setShowCompose(false); load(); }
    catch { toast.error('Failed to send'); }
  };

  return (
    <div>
      <PageHeader title="Messages" breadcrumbs={['Admin', 'Messages']}
        actions={<button className="btn-primary text-sm" onClick={() => setShowCompose(true)}>Compose</button>} />
      <div className="card">
        {loading ? <LoadingSpinner /> : messages.length === 0 ? <EmptyState title="No messages" /> : (
          <div className="divide-y divide-slate-100">
            {messages.map((m: any) => (
              <div key={m._id} className="py-3 px-2">
                <div className="flex items-center justify-between">
                  <span className="font-medium text-slate-800 text-sm">{m.subject}</span>
                  <span className="text-xs text-slate-400">{new Date(m.createdAt).toLocaleDateString('en-IN')}</span>
                </div>
                <p className="text-xs text-slate-500 mt-0.5">From: {m.fromUserId?.name} · To: {m.toUserId?.name || m.broadcastRole || 'Broadcast'}</p>
                <p className="text-sm text-slate-600 mt-1">{m.body}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <Modal open={showCompose} onClose={() => setShowCompose(false)} title="Compose Message">
        <div className="space-y-4">
          <div>
            <label className="label">Broadcast to Role</label>
            <select className="input" value={form.broadcastRole} onChange={e => setForm(p => ({ ...p, broadcastRole: e.target.value }))}>
              <option value="">Select role...</option>
              <option value="connector">All Connectors</option>
              <option value="company">All Companies</option>
              <option value="bank">All Banks</option>
            </select>
          </div>
          <div><label className="label">Subject *</label><input className="input" value={form.subject} onChange={e => setForm(p => ({ ...p, subject: e.target.value }))} /></div>
          <div><label className="label">Message *</label><textarea className="input h-24 resize-none" value={form.body} onChange={e => setForm(p => ({ ...p, body: e.target.value }))} /></div>
          <div className="flex gap-3 justify-end">
            <button className="btn-secondary" onClick={() => setShowCompose(false)}>Cancel</button>
            <button className="btn-primary" onClick={send}>Send</button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

