import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { toast } from 'react-toastify';
import { authAPI } from '../../services/api';
import { FiMail, FiLock, FiEye, FiEyeOff, FiCreditCard } from 'react-icons/fi';

export function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPw, setShowPw] = useState(false);
  const [loading, setLoading] = useState(false);

  const ROLE_ROUTES: Record<string,string> = { admin: '/admin/dashboard', company: '/company/dashboard', connector: '/connector/dashboard', bank: '/bank/dashboard', sm: '/bank/dashboard' };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await login(email, password);
      toast.success('Login successful!');
      const res = await authAPI.me();
      navigate(ROLE_ROUTES[res.data.user.role] || '/');
    } catch (err: any) {
      toast.error(err?.response?.data?.message || 'Login failed');
    } finally { setLoading(false); }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-50 via-white to-blue-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2 mb-3">
            <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center"><FiCreditCard className="text-white" /></div>
            <span className="text-2xl font-extrabold text-primary">BANK ZONE</span>
          </div>
          <h1 className="text-2xl font-bold text-slate-800">Welcome back</h1>
          <p className="text-slate-500 text-sm mt-1">Sign in to your account</p>
        </div>
        <div className="card shadow-lg">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="label">Email Address</label>
              <div className="relative"><FiMail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input type="email" className="input pl-10" placeholder="you@example.com" value={email} onChange={e => setEmail(e.target.value)} required />
              </div>
            </div>
            <div>
              <label className="label">Password</label>
              <div className="relative"><FiLock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input type={showPw ? 'text' : 'password'} className="input pl-10 pr-10" placeholder="••••••••" value={password} onChange={e => setPassword(e.target.value)} required />
                <button type="button" onClick={() => setShowPw(v => !v)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">{showPw ? <FiEyeOff /> : <FiEye />}</button>
              </div>
            </div>
            <button type="submit" className="btn-primary w-full py-3" disabled={loading}>{loading ? 'Signing in...' : 'Sign In'}</button>
          </form>
          <div className="mt-4 p-3 bg-slate-50 rounded-lg">
            <p className="text-xs text-slate-500 font-medium mb-2">Demo Credentials:</p>
            <div className="text-xs text-slate-500 space-y-0.5">
              <div>Admin: admin@bankzone.com / Admin@123</div>
              <div>Company: company1@bankzone.com / Company@123</div>
              <div>Connector: connector1@bankzone.com / Connector@123</div>
              <div>Bank: bank1@bankzone.com / Bank@123</div>
              <div>SM: sm1@bankzone.com / SM@123</div>
            </div>
          </div>
          <p className="text-center text-sm text-slate-500 mt-4">Don't have an account? <Link to="/register" className="text-primary font-medium hover:underline">Register</Link></p>
        </div>
      </div>
    </div>
  );
}

export function RegisterPage() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ role: 'connector', name: '', email: '', mobile: '', password: '', companyName: '', bankName: '', dsaCode: '' });
  const [loading, setLoading] = useState(false);
  const set = (k: string, v: string) => setForm(p => ({ ...p, [k]: v }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await authAPI.register(form);
      toast.success('Registration successful! Please login.');
      navigate('/login');
    } catch (err: any) {
      toast.error(err?.response?.data?.message || 'Registration failed');
    } finally { setLoading(false); }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-50 via-white to-blue-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2 mb-3">
            <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center"><FiCreditCard className="text-white" /></div>
            <span className="text-2xl font-extrabold text-primary">BANK ZONE</span>
          </div>
          <h1 className="text-2xl font-bold text-slate-800">Create Account</h1>
        </div>
        <div className="card shadow-lg">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div><label className="label">Register As</label>
              <select className="input" value={form.role} onChange={e => set('role', e.target.value)}>
                <option value="connector">Connector</option><option value="company">DSA Company</option><option value="bank">Bank</option>
              </select>
            </div>
            <div><label className="label">Full Name *</label><input className="input" value={form.name} onChange={e => set('name', e.target.value)} required /></div>
            {form.role === 'company' && <div><label className="label">Company Name *</label><input className="input" value={form.companyName} onChange={e => set('companyName', e.target.value)} /></div>}
            {form.role === 'bank' && <>
              <div><label className="label">Bank Name *</label><input className="input" value={form.bankName} onChange={e => set('bankName', e.target.value)} /></div>
              <div><label className="label">DSA Code</label><input className="input" value={form.dsaCode} onChange={e => set('dsaCode', e.target.value)} /></div>
            </>}
            <div><label className="label">Email *</label><input type="email" className="input" value={form.email} onChange={e => set('email', e.target.value)} required /></div>
            <div><label className="label">Mobile</label><input className="input" value={form.mobile} onChange={e => set('mobile', e.target.value)} /></div>
            <div><label className="label">Password *</label><input type="password" className="input" value={form.password} onChange={e => set('password', e.target.value)} required minLength={6} /></div>
            <button type="submit" className="btn-primary w-full py-3" disabled={loading}>{loading ? 'Creating...' : 'Create Account'}</button>
          </form>
          <p className="text-center text-sm text-slate-500 mt-4">Already registered? <Link to="/login" className="text-primary font-medium hover:underline">Login</Link></p>
        </div>
      </div>
    </div>
  );
}
